            RMITestInterface stub = (RMITestInterface) UnicastRemoteObject.exportObject(impl,5564);

            Naming.bind(RMI_NAME,stub);

            System.out.println("RMI服务启动成功,服务地址:" + RMI_NAME);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

    }

}

